class OrderRepository:
    def __init__(self, db_conn):
        self.db = db_conn

    def record_redemption(self, coupon_id: str, user_id: str, order_id: str):
        query = "INSERT INTO coupon_redemptions (coupon_id, user_id, order_id, redeemed_at) VALUES (?, ?, ?, datetime('now'))"
        self.db.execute(query, (coupon_id, user_id, order_id))
